using System.Reflection;
using FugaTES.Aplicacao.Consultas.EmissoresSap;
namespace FugaTES.Testes;
public sealed class EmissoresSapScreenTests
{
 static EmissorSapLeitura Row(string bp="123")=>new(bp,"EMISSOR SINTÉTICO","PF",true,true,false,"TEST");
 static EmissoresSapPagina Page(string bp="123",string? next=null,int inicio=0)=>new([Row(bp)],next,2,inicio,DateTimeOffset.UtcNow);
 static Form Create(Fake source,IDisposable? owner=null)
 {var t=typeof(FugaTES.WinForms.FrmIntegracoes).Assembly.GetType("FugaTES.WinForms.Cadastros.FrmEmissoresSap");Assert.NotNull(t);return (Form)Activator.CreateInstance(t,[source,owner,null])!;}
 [Fact] public void Screen_is_read_only_with_filters_and_two_detail_views()=>Sta(()=>
 {using var f=Create(new());f.Show();Application.DoEvents();Assert.Contains("Emissores",f.Text);Assert.Contains(All(f).OfType<TextBox>(),x=>x.Name=="codigoEmissor");Assert.Contains(All(f).OfType<TextBox>(),x=>x.Name=="nomeEmissor");Assert.Contains(All(f).OfType<TabPage>(),x=>x.Text=="Dados SAP");Assert.Contains(All(f).OfType<TabPage>(),x=>x.Text=="JSON SAP");Assert.DoesNotContain(All(f).OfType<Button>(),b=>new[]{"Cadastrar","Enviar","Sincronizar","Reenviar"}.Any(x=>b.Text.Contains(x)));Assert.All(All(f).OfType<DataGridView>(),g=>Assert.True(g.ReadOnly));f.Close();});
 [Fact] public void Query_is_manual_and_uses_the_entered_filters()=>Sta(()=>
 {var fake=new Fake();using var f=Create(fake);f.Show();Application.DoEvents();Assert.Equal(0,fake.Calls);All(f).OfType<TextBox>().Single(x=>x.Name=="codigoEmissor").Text="00123";All(f).OfType<TextBox>().Single(x=>x.Name=="nomeEmissor").Text="TESTE";Run(f,"AtualizarAsync");Assert.Equal(new("00123","TESTE"),fake.Filter);var grid=All(f).OfType<DataGridView>().Single(x=>x.Name=="emissoresGrid");Assert.Single(grid.Rows.Cast<DataGridViewRow>());Assert.Contains(All(f).OfType<Label>(),x=>x.Text.Contains("CONECTADO")&&x.Text.Contains("110"));Assert.Contains(All(f).OfType<Label>(),x=>x.Text.Contains("Guardian")&&x.Text.Contains("não consultado"));f.Close();});
 [Fact] public void Next_and_previous_pages_do_not_trigger_duplicate_queries()=>Sta(()=>
 {var fake=new Fake{Query=(filter,cursor,ct)=>Task.FromResult(cursor is null?Page(next:"NEXT"):Page("456",null,1))};using var f=Create(fake);f.Show();Application.DoEvents();Run(f,"AtualizarAsync");var next=All(f).OfType<Button>().Single(x=>x.Name=="proximaEmissor");Assert.True(next.Enabled);next.PerformClick();Pump();Assert.Equal(2,fake.Calls);var previous=All(f).OfType<Button>().Single(x=>x.Name=="anteriorEmissor");Assert.True(previous.Enabled);previous.PerformClick();Pump();Assert.Equal(2,fake.Calls);var grid=All(f).OfType<DataGridView>().Single(x=>x.Name=="emissoresGrid");Assert.Equal("123",grid.Rows[0].Cells["Codigo"].Value);f.Close();});
 [Fact] public void JSON_and_details_are_from_the_reader_without_Guardian_mapping()=>Sta(()=>
 {var fake=new Fake();using var f=Create(fake);f.Show();Application.DoEvents();Run(f,"AtualizarAsync");Run(f,"CarregarDetalheAsync","123",true);var box=All(f).OfType<TextBox>().Single(x=>x.Name=="jsonEmissor");Assert.True(box.ReadOnly);Assert.Equal(fake.Detail.Json,box.Text);Assert.DoesNotContain("tipoEmissor",box.Text);var fields=All(f).OfType<DataGridView>().Single(x=>x.Name=="dadosEmissor");Assert.Equal("synthetic@example.invalid",fields.Rows[0].Cells["Valor"].Value);Assert.Equal(1,fake.DetailCalls);f.Close();});
 [Fact] public void Failure_is_distinguished_from_a_successful_empty_list()=>Sta(()=>
 {var fake=new Fake{Query=(f,c,ct)=>throw new EmissoresSapException("SAP_UNAUTHORIZED",401)};using var form=Create(fake);form.Show();Application.DoEvents();Run(form,"AtualizarAsync");Assert.Contains(All(form).OfType<Label>(),l=>l.Text.Contains("SAP_UNAUTHORIZED")&&l.Text.Contains("DESCONECTADO"));fake.Query=(f,c,ct)=>Task.FromResult(new EmissoresSapPagina([],null,0,0,DateTimeOffset.UtcNow));Run(form,"AtualizarAsync");Assert.Contains(All(form).OfType<Label>(),l=>l.Text.Contains("CONECTADO")&&!l.Text.Contains("DESCONECTADO"));Assert.Contains(All(form).OfType<Label>(),l=>l.Text.Contains("Nenhum emissor"));form.Close();});
 [Fact] public void Closing_the_screen_cancels_an_active_read_and_disposes_only_its_owner()=>Sta(()=>
 {var owner=new Owner();var fake=new Fake{Query=async(f,c,ct)=>{await Task.Delay(Timeout.Infinite,ct);return Page();}};var form=Create(fake,owner);form.Show();Application.DoEvents();var task=(Task)form.GetType().GetMethod("AtualizarAsync")!.Invoke(form,null)!;Pump();Assert.False(task.IsCompleted);form.Close();form.Dispose();Await(task);Assert.True(fake.LastToken.IsCancellationRequested);Assert.True(owner.Disposed);});
 [Fact] public void A_new_filter_clears_old_details_and_does_not_change_the_original_JSON()=>Sta(()=>
 {var fake=new Fake();using var form=Create(fake);form.Show();Application.DoEvents();Run(form,"AtualizarAsync");Run(form,"CarregarDetalheAsync","123",true);var json=fake.Detail.Json;Run(form,"AtualizarAsync");Assert.Equal(json,fake.Detail.Json);Assert.Empty(All(form).OfType<TextBox>().Single(x=>x.Name=="jsonEmissor").Text);form.Close();});
 [Fact] public void Minimum_size_keeps_both_read_panels_inside_the_viewport()=>Sta(()=>
 {using var f=Create(new());f.Show();f.Size=f.MinimumSize;f.PerformLayout();Application.DoEvents();var split=All(f).OfType<SplitContainer>().Single();Assert.True(split.Right<=split.Parent!.ClientSize.Width,"Read panels exceed the minimum window width.");Assert.Contains(All(f).OfType<Button>(),b=>b.Name=="consultarEmissor"&&b.Visible);f.Close();});
 sealed class Owner:IDisposable{public bool Disposed;public void Dispose()=>Disposed=true;}
 public sealed class Fake:IEmissoresSapConsulta
 {public int Calls,DetailCalls;public EmissoresSapFiltro? Filter;public CancellationToken LastToken;public Func<EmissoresSapFiltro,string?,CancellationToken,Task<EmissoresSapPagina>> Query=(f,c,ct)=>Task.FromResult(Page());public EmissorSapDetalhe Detail=new("123","{\"BusinessPartner\":\"123\",\"EmailAddress\":\"synthetic@example.invalid\"}",[new("Contato","EmailAddress","synthetic@example.invalid")],DateTimeOffset.UtcNow);public Task<EmissoresSapPagina> ConsultarAsync(EmissoresSapFiltro f,string? c,CancellationToken ct){Calls++;Filter=f;LastToken=ct;return Query(f,c,ct);}public Task<EmissorSapDetalhe> ObterDetalheAsync(string bp,CancellationToken ct){DetailCalls++;return Task.FromResult(Detail);}}
 static void Run(Form f,string method,params object[] args)=>Await((Task)f.GetType().GetMethod(method)!.Invoke(f,args)!);
 static void Await(Task t){var until=DateTime.UtcNow.AddSeconds(10);while(!t.IsCompleted&&DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(5);}Assert.True(t.IsCompleted);t.GetAwaiter().GetResult();Application.DoEvents();}
 static void Pump(){for(var i=0;i<5;i++){Application.DoEvents();Thread.Sleep(5);}}
 static IEnumerable<Control> All(Control c){foreach(Control x in c.Controls){yield return x;foreach(var child in All(x))yield return child;}}
 static void Sta(Action action){Exception? problem=null;var t=new Thread(()=>{try{action();}catch(Exception e){problem=e;}});t.SetApartmentState(ApartmentState.STA);t.Start();Assert.True(t.Join(TimeSpan.FromSeconds(25)));if(problem is not null)System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(problem).Throw();}
}
